  "warehouse_id": "4dfab06c923fe3cc",
  "query": "-- Create Feature Table accounts9ad208\n\n-- First, create a temporary table from the CSV files\nCREATE OR REPLACE TEMPORARY VIEW temp_batch_1 \nUSING CSV \nOPTIONS (path \"/Volumes/workspace/mlpab37b986/accounts9ad208_volume/batch_1.csv\", header \"true\", inferSchema \"true\");\n\nCREATE OR REPLACE TEMPORARY VIEW temp_batch_2 \nUSING CSV \nOPTIONS (path \"/Volumes/workspace/mlpab37b986/accounts9ad208_volume/batch_2.csv\", header \"true\", inferSchema \"true\");\n\nCREATE OR REPLACE TEMPORARY VIEW temp_batch_3 \nUSING CSV \nOPTIONS (path \"/Volumes/workspace/mlpab37b986/accounts9ad208_volume/batch_3.csv\", header \"true\", inferSchema \"true\");\n\n-- Union all batches\nCREATE OR REPLACE TEMPORARY VIEW all_batches AS\nSELECT * FROM temp_batch_1\nUNION ALL\nSELECT * FROM temp_batch_2\nUNION ALL\nSELECT * FROM temp_batch_3;\n\n-- For each row_id, keep only the row with the latest updated_at\nCREATE OR REPLACE TEMPORARY VIEW latest_revisions AS\nSELECT * FROM (\n  SELECT *,\n         ROW_NUMBER() OVER (PARTITION BY row_id ORDER BY updated_at DESC) as rank\n  FROM all_batches\n) WHERE rank = 1;\n\n-- Create the final Delta table in Unity Catalog\nCREATE TABLE IF NOT EXISTS workspace.mlpab37b986.accounts9ad208 \nUSING DELTA \nLOCATION '/Volumes/workspace/mlpab37b986/accounts9ad208' \nAS SELECT * FROM latest_revisions;\n\n-- Create online table for low-latency access\nCREATE ONLINE TABLE IF NOT EXISTS workspace.mlpab37b986.accounts9ad208_online \nAS SELECT * FROM workspace.mlpab37b986.accounts9ad208;"
}"}

